from collections import deque

def bfs(start, adj, n):
    visited = [False] * (n + 1)
    level = [-1] * (n + 1)
    queue = deque([start])
    visited[start] = True
    level[start] = 0
    while queue:
        node = queue.popleft()
        for neighbor in adj[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                level[neighbor] = level[node] + 1
                queue.append(neighbor)
    return level

